CREATE TABLE public.user_progress (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, topic_id TEXT NOT NULL, done BOOLEAN NOT NULL DEFAULT true, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, topic_id)); ALTER TABLE public.user_progress ENABLE ROW LEVEL SECURITY; CREATE POLICY up_sel ON public.user_progress FOR SELECT USING (auth.uid() = user_id); CREATE POLICY up_ins ON public.user_progress FOR INSERT WITH CHECK (auth.uid() = user_id); CREATE POLICY up_upd ON public.user_progress FOR UPDATE USING (auth.uid() = user_id); CREATE POLICY up_del ON public.user_progress FOR DELETE USING (auth.uid() = user_id); CREATE TABLE public.study_log (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, date DATE NOT NULL, subject TEXT NOT NULL, topic TEXT NOT NULL, minutes INTEGER NOT NULL CHECK (minutes > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX idx_study_log_user_date ON public.study_log(user_id, date); ALTER TABLE public.study_log ENABLE ROW LEVEL SECURITY; CREATE POLICY sl_sel ON public.study_log FOR SELECT USING (auth.uid() = user_id); CREATE POLICY sl_ins ON public.study_log FOR INSERT WITH CHECK (auth.uid() = user_id); CREATE POLICY sl_upd ON public.study_log FOR UPDATE USING (auth.uid() = user_id); CREATE POLICY sl_del ON public.study_log FOR DELETE USING (auth.uid() = user_id);